#include <cstddef>

std::size_t lengthOf(const char* text)
{
    std::size_t length{ 0 };
    while (text[length] != '\0')
    {
        ++length;
    }
    return length;
}

unitTests:
TEST("ordinary words") { CHECK_EQ(lengthOf("cat"), 3u); CHECK_EQ(lengthOf("hello world"), 11u); }
TEST("empty string") { CHECK_EQ(lengthOf(""), 0u); }
TEST("stops at the first terminator") { const char text[]{ 'a', 'b', '\0', 'c', 'd', '\0' }; CHECK_EQ(lengthOf(text), 2u); }

